#!/usr/bin/env python3
# INT-09 composite photo-edit request intake rights audit.
import csv, json, os
from collections import OrderedDict

AUDIT_DATE = "2026-03-31"
INP = "/app/input"
OUT = "/app"

PUBLIC_PAID = {"social_public", "print_for_sale"}
FINDING_ORDER = [
    "UNLICENSED_CHARACTER_USE",
    "THIRD_PARTY_BACKGROUND_UNLICENSED",
    "MISSING_MINOR_CONSENT",
    "COMMERCIAL_DISTRIBUTION_FLAG",
    "ALTERATION_DISCLOSURE_MISSING",
]

# ---------- load accounts ----------
accounts = OrderedDict()
with open(os.path.join(INP, "client_accounts.csv"), newline="") as f:
    for r in csv.DictReader(f):
        mac = r["master_agreement_covers"]
        covers = [] if mac == "none" else [c for c in mac.split(";") if c]
        accounts[r["account_id"]] = {
            "account_id": r["account_id"],
            "account_name": r["account_name"],
            "account_type": r["account_type"],
            "covers": covers,            # list of cleared distributions (empty if none/lapsed-handled later)
            "covers_raw": mac,
            "agreement_status": r["agreement_status"],
        }

# ---------- load licence register ----------
register = {}
with open(os.path.join(INP, "licensed_property_register.csv"), newline="") as f:
    for r in csv.DictReader(f):
        cd = r["covers_distribution"]
        covers_dist = ["all"] if cd == "all" else [c for c in cd.split(";") if c]
        register[r["license_id"]] = {
            "license_id": r["license_id"],
            "property_name": r["property_name"],
            "rights_holder": r["rights_holder"],
            "license_type": r["license_type"],
            "covers_distribution": covers_dist,
            "covers_distribution_raw": cd,
            "valid_until": r["valid_until"],
            "max_character_area_pct": r["max_character_area_pct"],
            "supersedes": r["supersedes"],
        }

# governing map: cited_id -> governing_id (follow supersession chain to the top)
supersede_of = {}
for r in register.values():
    if r["supersedes"] != "none":
        supersede_of[r["supersedes"]] = r["license_id"]
def governing_id(cited):
    cur = cited
    seen = set()
    while cur in supersede_of and cur not in seen:
        seen.add(cur)
        cur = supersede_of[cur]
    return cur

def covers(cited_lic_id, use_type, distribution):
    """Return (covers_bool, gov_row_or_None, reason)."""
    if cited_lic_id == "none":
        return (False, None, "no licence cited")
    if cited_lic_id not in register:
        return (False, None, f"licence id {cited_lic_id} not in register")
    gov_id = governing_id(cited_lic_id)
    gov = register[gov_id]
    if gov["license_type"] != use_type:
        return (False, gov, f"{gov_id} is {gov['license_type']}, not {use_type}")
    if "all" not in gov["covers_distribution"] and distribution not in gov["covers_distribution"]:
        return (False, gov, f"{gov_id} covers_distribution={gov['covers_distribution_raw']} does not list {distribution}")
    if gov["valid_until"] < AUDIT_DATE:
        return (False, gov, f"{gov_id} valid_until {gov['valid_until']} ended before audit date")
    return (True, gov, f"{gov_id} covers {use_type} for {distribution}, valid to {gov['valid_until']}")

# ---------- load request log ----------
requests = []
with open(os.path.join(INP, "composite_request_log.csv"), newline="") as f:
    for r in csv.DictReader(f):
        requests.append(r)

audited = [r for r in requests if r["intake_status"] != "withdrawn"]

# ---------- apply §3-§7 ----------
per_request = OrderedDict()   # request_id -> list of (finding, reason)
for r in audited:
    rid = r["request_id"]
    dist = r["intended_distribution"]
    findings = []

    # §3 Licensed-character use
    if r["character_property"] != "none":
        if dist == "personal_only":
            # personal-use allowance clears §3 (licence test + prominence cap)
            area = None
            if r["character_px_area"] not in ("none", "", None) and r["canvas_px_area"] not in ("none", "", None):
                area = float(r["character_px_area"]) / float(r["canvas_px_area"]) * 100
            reason = f"personal_only allowance clears §3"
            if area is not None:
                cit = r["character_license_id"]
                if cit in register:
                    g = register[governing_id(cit)]
                    if g["max_character_area_pct"] != "none" and area > float(g["max_character_area_pct"]):
                        reason += f" (character area {area:.4g}% would exceed {g['license_id']} cap {g['max_character_area_pct']}%, but allowance governs)"
            findings.append(("_cleared_s3", reason))
        else:
            ok, gov, why = covers(r["character_license_id"], "character", dist)
            if ok:
                cap = gov["max_character_area_pct"]
                if cap == "none":
                    findings.append(("_clean_s3", f"{gov['license_id']} covers, no cap"))
                else:
                    area = float(r["character_px_area"]) / float(r["canvas_px_area"]) * 100
                    if area > float(cap):
                        findings.append(("UNLICENSED_CHARACTER_USE",
                            f"{gov['license_id']} covers distribution & is in date, but character area {area:.4g}% exceeds cap {cap}% (governing row {gov['license_id']})"
                            + (f"; request cites {r['character_license_id']}" if r['character_license_id'] != gov['license_id'] else "")))
                    else:
                        findings.append(("_clean_s3", f"{gov['license_id']} covers, area {area:.4g}% within cap {cap}%"))
            else:
                findings.append(("UNLICENSED_CHARACTER_USE", why))
    # else: no character property -> §3 does not apply

    # §4 Third-party backgrounds
    bs = r["background_source"]
    if bs == "customer_original":
        findings.append(("_clean_s4", "customer_original background"))
    elif bs == "third_party_unlicensed":
        findings.append(("THIRD_PARTY_BACKGROUND_UNLICENSED",
            "background_source=third_party_unlicensed; unlicensed on its own record (cited id not looked up)"))
    elif bs == "third_party_licensed":
        ok, gov, why = covers(r["background_license_id"], "background", dist)
        if ok:
            findings.append(("_clean_s4", f"{gov['license_id']} covers background for {dist}"))
        else:
            findings.append(("THIRD_PARTY_BACKGROUND_UNLICENSED", why))

    # §5 Minor consent
    if r["subject_is_minor"] == "True":
        ct = r["minor_consent_type"]
        present = ct != "none"
        current = r["minor_consent_valid_until"] >= AUDIT_DATE
        if ct == "basic":
            wide = dist in ("personal_only", "client_internal")
            wide_why = "basic consent covers personal_only/client_internal only"
        elif ct == "publicity":
            wide = True
            wide_why = "publicity consent covers every distribution"
        else:
            wide = False
            wide_why = f"consent type {ct} not wide enough"
        fails = []
        if not present: fails.append(f"not present (minor_consent_type={ct})")
        if not current: fails.append(f"not current (valid_until {r['minor_consent_valid_until']} < {AUDIT_DATE})")
        if not wide: fails.append(f"not wide enough ({wide_why}; distribution {dist})")
        if fails:
            findings.append(("MISSING_MINOR_CONSENT", "; ".join(fails)))
        else:
            findings.append(("_clean_s5", f"{ct} consent present, current, wide enough for {dist}"))
    # else: §5 does not apply

    # §6 Commercial distribution routing
    if dist in PUBLIC_PAID:
        a = accounts[r["account_id"]]
        if a["agreement_status"] == "active" and dist in a["covers"]:
            findings.append(("_clean_s6", f"{r['account_id']} active, master_agreement_covers names {dist}"))
        else:
            if a["agreement_status"] != "active":
                why = f"{r['account_id']} agreement_status={a['agreement_status']} (lapsed covers nothing); recorded covers={a['covers_raw']}"
            else:
                why = f"{r['account_id']} active but master_agreement_covers={a['covers_raw']} does not name {dist}"
            findings.append(("COMMERCIAL_DISTRIBUTION_FLAG", why))
    else:
        findings.append(("_clean_s6", f"distribution {dist} is not public/paid, no routing"))

    # §7 Alteration disclosure
    if r["alteration_level"] == "substantive" and dist in PUBLIC_PAID:
        if r["alteration_disclosure_on_file"] == "True":
            findings.append(("_clean_s7", "substantive to public/paid, disclosure on file"))
        else:
            findings.append(("ALTERATION_DISCLOSURE_MISSING",
                f"substantive alteration to {dist}, alteration_disclosure_on_file=False"))
    else:
        findings.append(("_clean_s7", f"no disclosure owed (alteration={r['alteration_level']}, dist={dist})"))

    per_request[rid] = findings

# ---------- per-request findings (only real findings, in §-order) ----------
def real_findings(rid):
    return [f[0] for f in per_request[rid] if not f[0].startswith("_")]

# ---------- §8 account escalation ----------
batch_share = sum(1 for rid in per_request if real_findings(rid)) / len(per_request)
acct_reqs = OrderedDict()
for r in audited:
    acct_reqs.setdefault(r["account_id"], []).append(r["request_id"])

account_rollup = OrderedDict()
escalated = []
for aid in accounts:
    rids = acct_reqs.get(aid, [])
    rc = len(rids)
    flagged = sum(1 for rid in rids if real_findings(rid))
    max_findings = max((len(real_findings(rid)) for rid in rids), default=0)
    share = flagged / rc if rc else 0
    limb1 = share > batch_share
    limb2 = max_findings >= 3
    esc = "ESCALATION_REQUIRED" if (limb1 or limb2) else "none"
    account_rollup[aid] = {
        "account_id": aid,
        "account_type": accounts[aid]["account_type"],
        "request_count": rc,
        "flagged_requests": flagged,
        "escalation": esc,
        "share": share,
        "limb1": limb1,
        "limb2": limb2,
        "max_findings": max_findings,
    }
    if esc == "ESCALATION_REQUIRED":
        escalated.append(aid)

# ---------- §9 figures ----------
flagged_count = sum(1 for rid in per_request if real_findings(rid))
compliant_count = len(per_request) - flagged_count
finding_total = sum(len(real_findings(rid)) for rid in per_request)
def count_finding(name):
    return sum(1 for rid in per_request if name in real_findings(rid))

figures = OrderedDict([
    ("request_count", len(per_request)),
    ("account_count", sum(1 for a in accounts if acct_reqs.get(a))),
    ("flagged_count", flagged_count),
    ("compliant_count", compliant_count),
    ("finding_total", finding_total),
    ("character_count", count_finding("UNLICENSED_CHARACTER_USE")),
    ("background_count", count_finding("THIRD_PARTY_BACKGROUND_UNLICENSED")),
    ("consent_count", count_finding("MISSING_MINOR_CONSENT")),
    ("commercial_count", count_finding("COMMERCIAL_DISTRIBUTION_FLAG")),
    ("disclosure_count", count_finding("ALTERATION_DISCLOSURE_MISSING")),
    ("escalated_accounts", len(escalated)),
])

# ---------- write composite_request_audit.csv ----------
with open(os.path.join(OUT, "composite_request_audit.csv"), "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["request_id", "finding"])
    for rid in per_request:            # already in log order (audited only)
        rf = real_findings(rid)
        if not rf:
            w.writerow([rid, "none"])
        else:
            for code in rf:
                w.writerow([rid, code])

# ---------- write account_summary.csv ----------
with open(os.path.join(OUT, "account_summary.csv"), "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["account_id", "account_type", "request_count", "flagged_requests", "escalation"])
    for aid in account_rollup:
        a = account_rollup[aid]
        w.writerow([a["account_id"], a["account_type"], a["request_count"], a["flagged_requests"], a["escalation"]])

# ---------- write results.json ----------
with open(os.path.join(OUT, "results.json"), "w") as f:
    json.dump(figures, f, indent=2)
    f.write("\n")

# ---------- diagnostics dump for verification ----------
print("=== per-request findings (in log order) ===")
for rid in per_request:
    rf = real_findings(rid)
    print(rid, "->", ", ".join(rf) if rf else "none")
    for code, why in per_request[rid]:
        if not code.startswith("_"):
            print(f"      [{code}] {why}")
print()
print("=== figures ===")
for k, v in figures.items():
    print(f"{k}: {v}")
print()
print("=== account rollup ===")
for aid in account_rollup:
    a = account_rollup[aid]
    print(f"{aid} {a['account_type']} rc={a['request_count']} flagged={a['flagged_requests']} "
          f"share={a['share']:.4f} limb1={a['limb1']} maxf={a['max_findings']} limb2={a['limb2']} -> {a['escalation']}")
print()
print("batch_share =", round(batch_share, 6))
print("escalated =", escalated)
print("withdrawn (out of scope) =",
      [r["request_id"] for r in requests if r["intake_status"] == "withdrawn"])

